#!/usr/bin/env node
//
// A wizard walks a human through a manual procedure, step by step.
// Generated by the wizard skill. Run it with `node <this file>`.
//
// Everything above the "STAGES" marker is the wizard library: do not hand-edit
// it. Author the per-step stages below the marker.

import fs from "node:fs";
import readline from "node:readline";
import { Writable } from "node:stream";
import { spawnSync } from "node:child_process";

// ──────────────────────────────────────────────────────────────────────────
// Wizard library: delightful, consistent UX, identical across every wizard.
// ──────────────────────────────────────────────────────────────────────────

const tty = Boolean(process.stdout.isTTY);
const sgr = (code) => (tty ? `\x1b[${code}m` : "");
const BOLD = sgr(1), DIM = sgr(2), RESET = sgr(0);
const BLUE = sgr(34), GREEN = sgr(32), YELLOW = sgr(33);

// Author sets this at the top of the stages section.
let TOTAL_STAGES = 0;

let stageIndex = 0;
const ENV_FILE = process.env.ENV_FILE || ".env";
const writtenEnv = []; // KEYs written to ENV_FILE this run
const writtenSecret = []; // secret NAMEs set this run
const skipped = []; // things we couldn't do (e.g. gh missing)

// One readline for the whole run. Its output can be muted, so askSecret's
// typing never reaches the screen. Lines that arrive before a question is
// asked (piped input) wait in a queue, one answer each.
let muted = false;
const output = new Writable({
  write(chunk, encoding, done) {
    if (!muted) process.stdout.write(chunk, encoding);
    done();
  },
});
const rl = readline.createInterface({ input: process.stdin, output, terminal: tty });
const queued = [];
let answer = null;
rl.on("line", (line) => (answer ? answer(line) : queued.push(line)));
rl.on("SIGINT", () => {
  process.stdout.write("\n");
  process.exit(130);
});
rl.on("close", () => {
  // stdin ended while a question was open: stop rather than hang.
  if (answer) {
    process.stdout.write("\n");
    process.exit(1);
  }
});

function question(prompt, { hidden = false } = {}) {
  return new Promise((resolve) => {
    const done = (line) => {
      answer = null;
      if (muted) process.stdout.write("\n");
      muted = false;
      resolve(line.trim());
    };
    if (hidden) {
      process.stdout.write(prompt);
      muted = true;
      rl.setPrompt("");
    } else {
      rl.setPrompt(prompt);
    }
    rl.prompt();
    if (queued.length) done(queued.shift());
    else answer = done;
  });
}

// clear wipes the terminal so only the current step is on screen. No-op when
// output isn't a terminal, so piped logs stay readable.
function clear() {
  if (tty) process.stdout.write("\x1b[2J\x1b[3J\x1b[H");
}

// banner("Title") shows the opening frame: what this wizard does.
async function banner(title) {
  clear();
  console.log(`\n${BOLD}${BLUE}  ${title}${RESET}`);
  console.log(`${DIM}  ${TOTAL_STAGES} stages${RESET}\n`);
  console.log(`${DIM}  You drive the browser; this wizard tells you exactly what to do and`);
  console.log("  captures the values you copy back. Stop any time with Ctrl-C and re-run");
  console.log(`  later, since it remembers values already saved.${RESET}`);
  await pause("Ready to start?");
}

// stage("Name") clears the screen, then announces a stage and shows progress.
function stage(name) {
  clear();
  stageIndex += 1;
  console.log(`\n${BOLD}${BLUE}▸ Stage ${stageIndex}/${TOTAL_STAGES} · ${name}${RESET}`);
}

// say prints a plain instruction line; step is an action the human takes.
const say = (text) => console.log(`  ${text}`);
const step = (text) => console.log(`  ${BLUE}•${RESET} ${text}`);
const note = (text) => console.log(`  ${DIM}${text}${RESET}`);
const warn = (text) => console.log(`  ${YELLOW}⚠ ${text}${RESET}`);

// openUrl(url) opens it in the human's browser: Windows, macOS, Linux, WSL.
function openUrl(url) {
  console.log(`  ${GREEN}↗ opening${RESET} ${url}`);
  const candidates =
    process.platform === "win32" ? [["explorer.exe", [url]]]
    : process.platform === "darwin" ? [["open", [url]]]
    : [["wslview", [url]], ["explorer.exe", [url]], ["xdg-open", [url]]];
  for (const [command, args] of candidates) {
    // explorer.exe exits 1 even when it opened the page, so only a missing
    // command counts as a failure.
    const result = spawnSync(command, args, { stdio: "ignore" });
    if (!result.error) return;
  }
  warn(`couldn't open a browser, so visit it manually: ${url}`);
}

// pause("msg") waits for the human to confirm they've done the manual part.
async function pause(message = "Press Enter to continue") {
  await question(`  ${DIM}${message}${RESET} `);
}

// confirm("question") is a y/N gate; returns true on yes.
async function confirm(text) {
  const reply = await question(`  ${YELLOW}? ${text} [y/N]${RESET} `);
  return /^y/i.test(reply);
}

// existing(KEY): current value of KEY in ENV_FILE, if any, with writeEnv's single
// quotes or a plain dotenv double-quoted value undone.
function existing(key) {
  if (!fs.existsSync(ENV_FILE)) return "";
  const line = fs
    .readFileSync(ENV_FILE, "utf8")
    .split(/\r?\n/)
    .filter((l) => l.startsWith(`${key}=`))
    .at(-1);
  if (line === undefined) return "";
  let value = line.slice(key.length + 1);
  if (value.length >= 2 && value.startsWith("'") && value.endsWith("'")) {
    value = value.slice(1, -1).replaceAll("'\\''", "'");
  } else if (value.length >= 2 && value.startsWith('"') && value.endsWith('"')) {
    value = value.slice(1, -1);
    if (/[\\$"]/.test(value)) return ""; // escapes, $ or ": can't decode safely; ask again
  }
  return value;
}

// ask(KEY, "Prompt") returns the value typed. Offers the existing .env value
// as a default on re-runs (Enter keeps it). Visible input, for non-secrets.
async function ask(key, prompt) {
  const current = existing(key);
  const hint = current ? ` ${DIM}[Enter keeps current]${RESET}` : "";
  const input = await question(`  ${BOLD}${prompt}${RESET}${hint} `);
  return input || current;
}

// askSecret(KEY, "Prompt") is like ask, but input is hidden.
async function askSecret(key, prompt) {
  const current = existing(key);
  const hint = current ? ` ${DIM}[Enter keeps current]${RESET}` : "";
  const input = await question(`  ${BOLD}${prompt}${RESET}${hint} `, { hidden: true });
  return input || current;
}

// writeEnv(KEY, value) upserts KEY='value' into ENV_FILE (replaces any existing
// line). Idempotent. Creates ENV_FILE at mode 0600; writes through a symlink
// and keeps an existing file's mode.
function writeEnv(key, value) {
  if (!fs.existsSync(ENV_FILE)) fs.writeFileSync(ENV_FILE, "", { mode: 0o600 });
  const kept = fs
    .readFileSync(ENV_FILE, "utf8")
    .split(/\r?\n/)
    .filter((l) => l !== "" && !l.startsWith(`${key}=`));
  kept.push(`${key}='${value.replaceAll("'", "'\\''")}'`);
  fs.writeFileSync(ENV_FILE, kept.join("\n") + "\n");
  writtenEnv.push(key);
  console.log(`  ${GREEN}✓ wrote${RESET} ${key} → ${ENV_FILE}`);
}

const ghReady = () => {
  const result = spawnSync("gh", ["auth", "status"], { stdio: "ignore" });
  return !result.error && result.status === 0;
};

// setSecret(NAME, value) sets a GitHub Actions repo secret via gh. Falls back
// to a warning (and records it) if gh is unavailable or unauthenticated.
function setSecret(name, value) {
  if (ghReady()) {
    const result = spawnSync("gh", ["secret", "set", name], { input: value, stdio: ["pipe", "ignore", "ignore"] });
    if (!result.error && result.status === 0) {
      writtenSecret.push(name);
      console.log(`  ${GREEN}✓ set${RESET} GitHub secret ${name}`);
      return;
    }
  }
  skipped.push(`GitHub secret ${name} (set it manually: gh secret set ${name})`);
  warn(`skipped GitHub secret ${name}: gh not ready; set it later`);
}

// setVar(NAME, value) sets a GitHub Actions repo variable (non-secret).
function setVar(name, value) {
  if (ghReady()) {
    const result = spawnSync("gh", ["variable", "set", name, "--body", value], { stdio: "ignore" });
    if (!result.error && result.status === 0) {
      console.log(`  ${GREEN}✓ set${RESET} GitHub variable ${name}`);
      return;
    }
  }
  skipped.push(`GitHub variable ${name}`);
  warn(`skipped GitHub variable ${name}, gh not ready; set it later`);
}

// finish clears, then shows a closing summary of everything configured.
function finish() {
  clear();
  console.log(`\n${BOLD}${GREEN}  ✓ Setup complete${RESET}`);
  if (writtenEnv.length) note(`wrote ${writtenEnv.length} value(s) to ${ENV_FILE}: ${writtenEnv.join(" ")}`);
  if (writtenSecret.length) note(`set ${writtenSecret.length} GitHub secret(s): ${writtenSecret.join(" ")}`);
  if (skipped.length) {
    console.log();
    warn("still to do by hand:");
    for (const s of skipped) note(`  - ${s}`);
  }
  console.log();
  rl.close();
}

// ──────────────────────────────────────────────────────────────────────────
// STAGES: author this section. One stage() per step the human takes.
// Replace the example below. Set TOTAL_STAGES to match the stages you write.
// ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES = 1;

await banner("Stripe setup");

// ── Example stage: replace with your real steps ───────────────────────────
stage("Stripe: API keys");
say("We'll grab your Stripe test keys and store them for local dev + CI.");
openUrl("https://dashboard.stripe.com/test/apikeys");
step("On the API keys page, copy the Publishable key (starts pk_test_).");
const publishableKey = await ask("STRIPE_PUBLISHABLE_KEY", "Paste the publishable key:");
step("Click 'Reveal test key' on the Secret key row, then copy it.");
const secretKey = await askSecret("STRIPE_SECRET_KEY", "Paste the secret key:");
writeEnv("STRIPE_PUBLISHABLE_KEY", publishableKey);
writeEnv("STRIPE_SECRET_KEY", secretKey);
setSecret("STRIPE_SECRET_KEY", secretKey); // CI needs this one
// ──────────────────────────────────────────────────────────────────────────

finish();
